import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1, 1, dim)
        # Adaptive population size to balance exploration and evaluation overhead
        self.pop_size = max(6, int(budget * 0.06))
        self.rng = np.random.default_rng(42)

    def _evaluate(self, x, func):
        if self.evals >= self.budget: 
            return float('inf')
        x_clean = np.clip(np.asarray(x), -1.0, 1.0)
        f = func(x_clean)
        self.evals += 1
        if np.isfinite(f) and f < self.best_f:
            self.best_f = f
            self.best_x = x_clean.copy()
        return f

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: 
            return self.best_f, self.best_x

        # LHS Initialization
        pop = _lhs(n_samples=self.pop_size, n_dim=self.dim)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)

        fitness = np.full(self.pop_size, float('inf'))
        for i in range(self.pop_size):
            fitness[i] = self._evaluate(pop[i], func)
            if self.evals >= self.budget: 
                return self.best_f, self.best_x

        # Self-adaptive DE parameters
        F, CR = 0.5, 0.75
        # Proportional generation cap to stay within budget while enabling convergence
        remaining = self.budget - self.evals
        max_gen = max(2, min(int(remaining / (self.pop_size * 1.5)), 8))

        for gen in range(max_gen):
            if self.evals >= self.budget: 
                break
            for i in range(self.pop_size):
                if self.evals >= self.budget: 
                    break

                # Self-adaptive mutation with Lévy flight perturbation
                idxs = self.rng.choice(self.pop_size, 3, replace=False)
                while np.any(idxs == i):
                    idxs = self.rng.choice(self.pop_size, 3, replace=False)
                r1, r2, r3 = idxs

                # Standard DE/rand/1/bin
                mutant = pop[r1] + F * (pop[r2] - pop[r3])

                # Lévy flight for escaping cliffs/local minima
                levy_scale = 0.1 * np.exp(-gen / max(max_gen, 1))
                levy = self.rng.standard_cauchy(self.dim)
                mutant += levy * levy_scale

                # Gradient-aware bias (continuous subspace only)
                if grad_func is not None:
                    g = grad_func(pop[i])
                    if g is not None and g.shape[0] == 18:
                        grad_bias = np.zeros(self.dim)
                        grad_bias[:18] = g
                        step_size = 0.06 * (1.0 + 0.15 * np.sin(self.evals * 0.1))
                        mutant -= grad_bias * step_size

                mutant = np.clip(mutant, -1.0, 1.0)

                # Dynamic CR adaptation
                if self.rng.random() < 0.3:
                    CR = min(0.95, max(0.5, CR + self.rng.uniform(-0.08, 0.08)))

                cr_mask = self.rng.random(self.dim) < CR
                trial = np.where(cr_mask, mutant, pop[i])

                f_trial = self._evaluate(trial, func)
                if f_trial < fitness[i]:
                    pop[i] = trial
                    fitness[i] = f_trial
                    # Adapt F based on recent success rate
                    F = min(1.0, F * 1.02)

        # Sophisticated Local Search with dynamic budget allocation
        if grad_func is not None and self.evals < self.budget * 0.85:
            best_idx = np.argmin(fitness)
            best_pop_x = pop[best_idx].copy()
            fixed_cats = best_pop_x[18:24].copy()

            # 18D wrapper handles continuous vars, maintains 24D full vector internally
            def cost_wrap(x_c):
                return self._evaluate(np.concatenate([np.asarray(x_c), fixed_cats]), func)

            def grad_wrap(x_c):
                full_x = np.concatenate([np.asarray(x_c), fixed_cats])
                return grad_func(full_x)

            # Allocate remaining budget wisely (1 iteration typically costs 1-2 evals)
            ls_budget = max(12, int((self.budget - self.evals) * 0.35))
            res = minimize(cost_wrap, best_pop_x[:18], jac=grad_wrap, method='L-BFGS-B', 
                           bounds=[(-1.0, 1.0)] * 18, options={'maxiter': min(ls_budget, self.budget - self.evals), 'ftol': 1e-4})

            if np.isfinite(res.fun) and res.fun < self.best_f:
                self.best_f = res.fun
                self.best_x = np.concatenate([res.x, fixed_cats])

        return self.best_f, self.best_x
